/**
 * Phone validation field highlighting for WooCommerce block checkout.
 *
 * Presentation only. Block checkout shows Store API errors in a generic banner
 * with no reference to the field, so the banner text is compared with the exact
 * messages generated by PHP for the current locale (window.shift64PhoneValidation,
 * see Checkout\Assets). No wording lives in this file.
 *
 * Scrolling is left to WooCommerce Blocks.
 *
 * @package Shift64\SmartPhoneValidation
 */

(function() {
	'use strict';

	var config = window.shift64PhoneValidation || {};
	var messages = config.messages || {};
	var FIELD_TYPES = ['billing', 'shipping'];
	var NOTICE_SELECTOR = '.wc-block-components-notice-banner.is-error, .wc-block-store-notice.is-error';

	/**
	 * Find the phone input for a field type.
	 *
	 * With "use same address for billing" checked only the shipping form is
	 * rendered and its phone doubles as the billing phone.
	 *
	 * @param {string} type 'billing' or 'shipping'.
	 * @return {Element|null} The input element or null.
	 */
	function findPhoneField(type) {
		var field = document.getElementById(type + '-phone');

		if (!field && type === 'billing') {
			field = document.getElementById('shipping-phone');
		}

		return field;
	}

	function findFieldWrapper(input) {
		return input.closest('.wc-block-components-text-input') || input.parentElement;
	}

	function highlightField(type) {
		var input = findPhoneField(type);
		if (!input) {
			return;
		}

		// .has-error is the class WooCommerce Blocks styles itself.
		findFieldWrapper(input).classList.add('has-error');
		input.setAttribute('aria-invalid', 'true');
		input.setAttribute('data-shift64-phone-error', type);
	}

	function clearFieldError(input) {
		findFieldWrapper(input).classList.remove('has-error');
		input.setAttribute('aria-invalid', 'false');
		input.removeAttribute('data-shift64-phone-error');
	}

	/**
	 * Tell which phone field a notice is about.
	 *
	 * @param {string} text Notice text.
	 * @return {string|null} 'billing', 'shipping' or null when it is not our notice.
	 */
	function detectFieldType(text) {
		for (var i = 0; i < FIELD_TYPES.length; i++) {
			var list = messages[FIELD_TYPES[i]] || [];

			for (var j = 0; j < list.length; j++) {
				if (text.indexOf(list[j]) !== -1) {
					return FIELD_TYPES[i];
				}
			}
		}

		return null;
	}

	function processNotices() {
		document.querySelectorAll(NOTICE_SELECTOR).forEach(function(notice) {
			var type = detectFieldType(notice.textContent || '');

			if (type) {
				highlightField(type);
			}
		});
	}

	function containsNotice(node) {
		return node.nodeType === 1 && (node.matches(NOTICE_SELECTOR) || node.querySelector(NOTICE_SELECTOR));
	}

	function init() {
		processNotices();

		// Notices are rendered by React after the Store API responds.
		new MutationObserver(function(mutations) {
			var noticeAdded = mutations.some(function(mutation) {
				return Array.prototype.some.call(mutation.addedNodes, containsNotice);
			});

			if (noticeAdded) {
				processNotices();
			}
		}).observe(document.body, { childList: true, subtree: true });

		// Delegated, so it also covers fields React renders later.
		document.addEventListener('input', function(event) {
			if (event.target.hasAttribute && event.target.hasAttribute('data-shift64-phone-error')) {
				clearFieldError(event.target);
			}
		});
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}

})();
